  "Pairing is preserved. Switching networks does not require pairing again; this device signs back in with its saved key.": "Bleibt bestehen. Ein Netzwerkwechsel braucht keine neue Kopplung; dieses Gerät meldet sich mit seinem gespeicherten Schlüssel wieder an.",
  "Data displayed may be obsolete. Drafts remain stored on this device and are transferred after reconnection.": "Angezeigte Daten können veraltet sein. Entwürfe bleiben auf diesem Gerät gespeichert und werden nach der Wiederverbindung übertragen.",
  "This helps, in this order:": "Das hilft, in dieser Reihenfolge:",
  "Tailscale connected on this device? Mobile and external Wi-Fi need the active tailscale connection.": "Tailscale auf diesem Gerät verbunden? Mobilfunk und fremdes WLAN brauchen die aktive Tailscale-Verbindung.",
