  "Then reconnect. Do not clear browser storage; it contains the pairing credentials.": "Erst danach erneut verbinden. Den Browserspeicher nicht löschen; er enthält die Kopplung.",
  "After building on the PC, fully quit and restart ADE there; closing the window leaves the old build running. Then reload this page.": "Nach einem Neubau am PC muss ADE dort vollständig beendet und neu gestartet werden; das Schliessen des Fensters lässt den alten Stand weiterlaufen. Danach diese Seite neu laden.",
