  "Reset diverging participant worktrees to the orchestrator base": "Abweichende Teilnehmer-Worktrees auf die Orchestrator-Basis zurücksetzen",
  "Before starting, ADE archives each diverging worktree under refs/ade/archive/<run>/<participant>, then resets it to the orchestrator worktree HEAD. Dirty worktrees and worktrees used by an active run are left untouched.": "Vor dem Start sichert ADE den bisherigen Stand jedes abweichenden Worktrees unter refs/ade/archive/<run>/<teilnehmer> und setzt ihn dann auf den HEAD des Orchestrator-Worktrees. Dirty Worktrees und Worktrees eines aktiven Runs werden nicht angefasst.",
  "Without this option, starting stops if a participant worktree differs from the orchestrator worktree HEAD and lists the affected worktrees.": "Ohne Häkchen bricht der Start ab, sobald ein Teilnehmer-Worktree nicht auf dem HEAD des Orchestrator-Worktrees steht, und nennt die betroffenen Worktrees.",
