  "Operation and instructions": "Arbeitsweise und Anweisungen",
  "These instructions specialize in new sessions with an agent profile. Repository instructions remain effective. Already running sessions keep their starting status.": "Diese Anweisungen spezialisieren neue Sitzungen mit Agent-Profil. Repository-Anweisungen bleiben wirksam. Bereits laufende Sitzungen behalten ihren Startstand.",
