  "The selected coding harness reads and edits files using your Ollama model. Choose a model that supports tools.": "Der gewählte Coding-Harness liest und bearbeitet Dateien mit deinem Ollama-Modell. Wähle ein Modell mit Werkzeugunterstützung.",
