  "Activate, then say \"computer.\" Personal greeting with the default ADE voice and a hint about the next dictation. The test listens for up to 20 seconds; leave this window open. Uses ElevenLabs for recognition and voice.": "Aktivieren, dann „Computer“ sagen. Persönliche Begrüssung mit der ADE-Standardstimme und einem Hinweis zum nächsten Diktat. Der Test hört bis zu 20 Sekunden zu; dieses Fenster offen lassen. Verwendet ElevenLabs für Erkennung und Stimme.",
